SET XACT_ABORT ON;
SELECT * INTO #Foods FROM OPENJSON(@payload,'$.Foods') WITH ([Id] nvarchar(64) '$.Id',[Name] nvarchar(256) '$.Name',[Category] nvarchar(128) '$.Category',[Price] decimal(28,8) '$.Price',[Active] bit '$.Active',[ImagePath] nvarchar(2048) '$.ImagePath',[Instructions] nvarchar(max) '$.Instructions');
SELECT * INTO #Ingredients FROM OPENJSON(@payload,'$.Ingredients') WITH ([Id] nvarchar(64) '$.Id',[Name] nvarchar(256) '$.Name',[Unit] nvarchar(32) '$.Unit',[Stock] decimal(28,8) '$.Stock',[Minimum] decimal(28,8) '$.Minimum',[AverageCost] decimal(38,18) '$.AverageCost');
SELECT * INTO #Services FROM OPENJSON(@payload,'$.Services') WITH ([Id] nvarchar(64) '$.Id',[Name] nvarchar(256) '$.Name',[Price] decimal(28,8) '$.Price',[Active] bit '$.Active');
SELECT * INTO #DiningTables FROM OPENJSON(@payload,'$.Tables') WITH ([Id] nvarchar(64) '$.Id',[Name] nvarchar(128) '$.Name',[Seats] int '$.Seats');
SELECT * INTO #Recipes FROM OPENJSON(@payload,'$.Recipes') WITH ([FoodId] nvarchar(64) '$.FoodId',[IngredientId] nvarchar(64) '$.IngredientId',[Quantity] decimal(28,8) '$.Quantity');
SELECT * INTO #Reservations FROM OPENJSON(@payload,'$.Reservations') WITH ([Id] nvarchar(64) '$.Id',[TableId] nvarchar(64) '$.TableId',[Customer] nvarchar(256) '$.Customer',[Phone] nvarchar(64) '$.Phone',[Time] datetime2(7) '$.Time',[Guests] int '$.Guests',[Status] nvarchar(40) '$.Status');
SELECT * INTO #Purchases FROM OPENJSON(@payload,'$.Purchases') WITH ([Id] nvarchar(64) '$.Id',[Date] datetime2(7) '$.Date',[Supplier] nvarchar(256) '$.Supplier',[Operator] nvarchar(256) '$.Operator');
SELECT * INTO #Orders FROM OPENJSON(@payload,'$.Sales') WITH ([Id] nvarchar(64) '$.Id',[TableId] nvarchar(64) '$.TableId',[TableName] nvarchar(128) '$.TableName',[Customer] nvarchar(256) '$.Customer',[Operator] nvarchar(256) '$.Operator',[CreatedAt] datetime2(7) '$.CreatedAt',[PaidAt] datetime2(7) '$.PaidAt',[Status] nvarchar(40) '$.Status',[Discount] decimal(28,8) '$.Discount',[PaymentMethod] nvarchar(40) '$.PaymentMethod',[Received] decimal(28,8) '$.Received');
SELECT CONVERT(nvarchar(64),JSON_VALUE(p.value,'$.Id')) AS [PurchaseId],CONVERT(int,l.[key]) AS [LineNo],m.* INTO #PurchaseLines FROM OPENJSON(@payload,'$.Purchases') p CROSS APPLY OPENJSON(p.value,'$.Lines') l CROSS APPLY OPENJSON(l.value) WITH ([IngredientId] nvarchar(64) '$.IngredientId',[Name] nvarchar(256) '$.Name',[Unit] nvarchar(32) '$.Unit',[Quantity] decimal(28,8) '$.Quantity',[UnitCost] decimal(28,8) '$.UnitCost') m;
SELECT CONVERT(nvarchar(64),JSON_VALUE(p.value,'$.Id')) AS [OrderId],CONVERT(int,l.[key]) AS [LineNo],m.* INTO #OrderItems FROM OPENJSON(@payload,'$.Sales') p CROSS APPLY OPENJSON(p.value,'$.Lines') l CROSS APPLY OPENJSON(l.value) WITH ([FoodId] nvarchar(64) '$.FoodId',[Name] nvarchar(256) '$.Name',[Quantity] int '$.Quantity',[UnitPrice] decimal(28,8) '$.UnitPrice',[Note] nvarchar(max) '$.Note') m;
SELECT CONVERT(nvarchar(64),JSON_VALUE(p.value,'$.Id')) AS [OrderId],CONVERT(int,l.[key]) AS [LineNo],m.* INTO #OrderServices FROM OPENJSON(@payload,'$.Sales') p CROSS APPLY OPENJSON(p.value,'$.Extras') l CROSS APPLY OPENJSON(l.value) WITH ([ServiceId] nvarchar(64) '$.ServiceId',[Name] nvarchar(256) '$.Name',[Quantity] int '$.Quantity',[UnitPrice] decimal(28,8) '$.UnitPrice') m;
DELETE d FROM dbo.[SalesOrderServices] d WHERE NOT EXISTS(SELECT 1 FROM #OrderServices s WHERE d.[OrderId]=s.[OrderId] AND d.[LineNo]=s.[LineNo]);
DELETE d FROM dbo.[SalesOrderItems] d WHERE NOT EXISTS(SELECT 1 FROM #OrderItems s WHERE d.[OrderId]=s.[OrderId] AND d.[LineNo]=s.[LineNo]);
DELETE d FROM dbo.[StockReceiptItems] d WHERE NOT EXISTS(SELECT 1 FROM #PurchaseLines s WHERE d.[PurchaseId]=s.[PurchaseId] AND d.[LineNo]=s.[LineNo]);
DELETE d FROM dbo.[SalesOrders] d WHERE NOT EXISTS(SELECT 1 FROM #Orders s WHERE d.[Id]=s.[Id]);
DELETE d FROM dbo.[StockReceipts] d WHERE NOT EXISTS(SELECT 1 FROM #Purchases s WHERE d.[Id]=s.[Id]);
DELETE d FROM dbo.[TableReservations] d WHERE NOT EXISTS(SELECT 1 FROM #Reservations s WHERE d.[Id]=s.[Id]);
DELETE d FROM dbo.[RecipeIngredients] d WHERE NOT EXISTS(SELECT 1 FROM #Recipes s WHERE d.[FoodId]=s.[FoodId] AND d.[IngredientId]=s.[IngredientId]);
DELETE d FROM dbo.[DiningTables] d WHERE NOT EXISTS(SELECT 1 FROM #DiningTables s WHERE d.[Id]=s.[Id]);
DELETE d FROM dbo.[ExtraServices] d WHERE NOT EXISTS(SELECT 1 FROM #Services s WHERE d.[Id]=s.[Id]);
DELETE d FROM dbo.[Ingredients] d WHERE NOT EXISTS(SELECT 1 FROM #Ingredients s WHERE d.[Id]=s.[Id]);
DELETE d FROM dbo.[MenuItems] d WHERE NOT EXISTS(SELECT 1 FROM #Foods s WHERE d.[Id]=s.[Id]);
UPDATE d SET d.[Name]=s.[Name],d.[Category]=s.[Category],d.[Price]=s.[Price],d.[Active]=s.[Active],d.[ImagePath]=s.[ImagePath],d.[Instructions]=s.[Instructions] FROM dbo.[MenuItems] d JOIN #Foods s ON d.[Id]=s.[Id];
INSERT dbo.[MenuItems] ([Id],[Name],[Category],[Price],[Active],[ImagePath],[Instructions]) SELECT s.[Id],s.[Name],s.[Category],s.[Price],s.[Active],s.[ImagePath],s.[Instructions] FROM #Foods s WHERE NOT EXISTS(SELECT 1 FROM dbo.[MenuItems] d WHERE d.[Id]=s.[Id]);
UPDATE d SET d.[Name]=s.[Name],d.[Unit]=s.[Unit],d.[Stock]=s.[Stock],d.[Minimum]=s.[Minimum],d.[AverageCost]=s.[AverageCost] FROM dbo.[Ingredients] d JOIN #Ingredients s ON d.[Id]=s.[Id];
INSERT dbo.[Ingredients] ([Id],[Name],[Unit],[Stock],[Minimum],[AverageCost]) SELECT s.[Id],s.[Name],s.[Unit],s.[Stock],s.[Minimum],s.[AverageCost] FROM #Ingredients s WHERE NOT EXISTS(SELECT 1 FROM dbo.[Ingredients] d WHERE d.[Id]=s.[Id]);
UPDATE d SET d.[Name]=s.[Name],d.[Price]=s.[Price],d.[Active]=s.[Active] FROM dbo.[ExtraServices] d JOIN #Services s ON d.[Id]=s.[Id];
INSERT dbo.[ExtraServices] ([Id],[Name],[Price],[Active]) SELECT s.[Id],s.[Name],s.[Price],s.[Active] FROM #Services s WHERE NOT EXISTS(SELECT 1 FROM dbo.[ExtraServices] d WHERE d.[Id]=s.[Id]);
UPDATE d SET d.[Name]=s.[Name],d.[Seats]=s.[Seats] FROM dbo.[DiningTables] d JOIN #DiningTables s ON d.[Id]=s.[Id];
INSERT dbo.[DiningTables] ([Id],[Name],[Seats]) SELECT s.[Id],s.[Name],s.[Seats] FROM #DiningTables s WHERE NOT EXISTS(SELECT 1 FROM dbo.[DiningTables] d WHERE d.[Id]=s.[Id]);
UPDATE d SET d.[Quantity]=s.[Quantity] FROM dbo.[RecipeIngredients] d JOIN #Recipes s ON d.[FoodId]=s.[FoodId] AND d.[IngredientId]=s.[IngredientId];
INSERT dbo.[RecipeIngredients] ([FoodId],[IngredientId],[Quantity]) SELECT s.[FoodId],s.[IngredientId],s.[Quantity] FROM #Recipes s WHERE NOT EXISTS(SELECT 1 FROM dbo.[RecipeIngredients] d WHERE d.[FoodId]=s.[FoodId] AND d.[IngredientId]=s.[IngredientId]);
UPDATE d SET d.[TableId]=s.[TableId],d.[Customer]=s.[Customer],d.[Phone]=s.[Phone],d.[Time]=s.[Time],d.[Guests]=s.[Guests],d.[Status]=s.[Status] FROM dbo.[TableReservations] d JOIN #Reservations s ON d.[Id]=s.[Id];
INSERT dbo.[TableReservations] ([Id],[TableId],[Customer],[Phone],[Time],[Guests],[Status]) SELECT s.[Id],s.[TableId],s.[Customer],s.[Phone],s.[Time],s.[Guests],s.[Status] FROM #Reservations s WHERE NOT EXISTS(SELECT 1 FROM dbo.[TableReservations] d WHERE d.[Id]=s.[Id]);
UPDATE d SET d.[Date]=s.[Date],d.[Supplier]=s.[Supplier],d.[Operator]=s.[Operator] FROM dbo.[StockReceipts] d JOIN #Purchases s ON d.[Id]=s.[Id];
INSERT dbo.[StockReceipts] ([Id],[Date],[Supplier],[Operator]) SELECT s.[Id],s.[Date],s.[Supplier],s.[Operator] FROM #Purchases s WHERE NOT EXISTS(SELECT 1 FROM dbo.[StockReceipts] d WHERE d.[Id]=s.[Id]);
UPDATE d SET d.[TableId]=s.[TableId],d.[TableName]=s.[TableName],d.[Customer]=s.[Customer],d.[Operator]=s.[Operator],d.[CreatedAt]=s.[CreatedAt],d.[PaidAt]=s.[PaidAt],d.[Status]=s.[Status],d.[Discount]=s.[Discount],d.[PaymentMethod]=s.[PaymentMethod],d.[Received]=s.[Received] FROM dbo.[SalesOrders] d JOIN #Orders s ON d.[Id]=s.[Id];
INSERT dbo.[SalesOrders] ([Id],[TableId],[TableName],[Customer],[Operator],[CreatedAt],[PaidAt],[Status],[Discount],[PaymentMethod],[Received]) SELECT s.[Id],s.[TableId],s.[TableName],s.[Customer],s.[Operator],s.[CreatedAt],s.[PaidAt],s.[Status],s.[Discount],s.[PaymentMethod],s.[Received] FROM #Orders s WHERE NOT EXISTS(SELECT 1 FROM dbo.[SalesOrders] d WHERE d.[Id]=s.[Id]);
UPDATE d SET d.[IngredientId]=s.[IngredientId],d.[Name]=s.[Name],d.[Unit]=s.[Unit],d.[Quantity]=s.[Quantity],d.[UnitCost]=s.[UnitCost] FROM dbo.[StockReceiptItems] d JOIN #PurchaseLines s ON d.[PurchaseId]=s.[PurchaseId] AND d.[LineNo]=s.[LineNo];
INSERT dbo.[StockReceiptItems] ([PurchaseId],[LineNo],[IngredientId],[Name],[Unit],[Quantity],[UnitCost]) SELECT s.[PurchaseId],s.[LineNo],s.[IngredientId],s.[Name],s.[Unit],s.[Quantity],s.[UnitCost] FROM #PurchaseLines s WHERE NOT EXISTS(SELECT 1 FROM dbo.[StockReceiptItems] d WHERE d.[PurchaseId]=s.[PurchaseId] AND d.[LineNo]=s.[LineNo]);
UPDATE d SET d.[FoodId]=s.[FoodId],d.[Name]=s.[Name],d.[Quantity]=s.[Quantity],d.[UnitPrice]=s.[UnitPrice],d.[Note]=s.[Note] FROM dbo.[SalesOrderItems] d JOIN #OrderItems s ON d.[OrderId]=s.[OrderId] AND d.[LineNo]=s.[LineNo];
INSERT dbo.[SalesOrderItems] ([OrderId],[LineNo],[FoodId],[Name],[Quantity],[UnitPrice],[Note]) SELECT s.[OrderId],s.[LineNo],s.[FoodId],s.[Name],s.[Quantity],s.[UnitPrice],s.[Note] FROM #OrderItems s WHERE NOT EXISTS(SELECT 1 FROM dbo.[SalesOrderItems] d WHERE d.[OrderId]=s.[OrderId] AND d.[LineNo]=s.[LineNo]);
UPDATE d SET d.[ServiceId]=s.[ServiceId],d.[Name]=s.[Name],d.[Quantity]=s.[Quantity],d.[UnitPrice]=s.[UnitPrice] FROM dbo.[SalesOrderServices] d JOIN #OrderServices s ON d.[OrderId]=s.[OrderId] AND d.[LineNo]=s.[LineNo];
INSERT dbo.[SalesOrderServices] ([OrderId],[LineNo],[ServiceId],[Name],[Quantity],[UnitPrice]) SELECT s.[OrderId],s.[LineNo],s.[ServiceId],s.[Name],s.[Quantity],s.[UnitPrice] FROM #OrderServices s WHERE NOT EXISTS(SELECT 1 FROM dbo.[SalesOrderServices] d WHERE d.[OrderId]=s.[OrderId] AND d.[LineNo]=s.[LineNo]);
UPDATE dbo.ApplicationState SET Version=CONVERT(int,JSON_VALUE(@payload,'$.Version')),Revision=CONVERT(bigint,JSON_VALUE(@payload,'$.Revision')),ReceiptSequence=CONVERT(int,JSON_VALUE(@payload,'$.ReceiptSequence')),PurchaseSequence=CONVERT(int,JSON_VALUE(@payload,'$.PurchaseSequence')),Initialized=1,ImportedAt=ISNULL(ImportedAt,SYSDATETIME()) WHERE Id=1;